// /frontend-react/src/components/MedicationHistoryPage.js

import React, { useState } from 'react';
import { useTranslation } from 'react-i18next';
import HeaderBar from './HeaderBar';

// --- MOCK DATA ---
const detail = {
    title: "Medications",
    // Data now includes ID, concise name for the button, and full details for the modal
    medicationList: [
        { id: 1, name: "Blood Pressure Pill (5mg)", details: "Take one pill once daily, every morning. Last taken: Today, 8:00 AM." },
        { id: 2, name: "Multivitamin", details: "Take one tablet once daily with breakfast. Last taken: Today, 9:00 AM." },
        { id: 3, name: "Aspirin (81mg)", details: "Take one tablet once daily with dinner. Last taken: Yesterday, 7:00 PM." },
    ],
    lastUpdated: "Dec 5, 2025",
    pdfLink: "Link_to_detailed_Medication_History_Report.pdf",
    color: { bg: '#E8F0FE', border: '#1A73E8', emoji: '💊' },
};

const PHONE_MAX_WIDTH = '450px';

// --- Internal Component: MedicationDetailsModal (The Pop-up) ---
const MedicationDetailsModal = ({ t, isEasyMode, medication, onClose }) => {
    if (!medication) return null;

    const modalStyle = {
        position: 'fixed',
        top: 0,
        left: 0,
        width: '100%',
        height: '100%',
        // FIX: Use semi-transparent background for true modal look
        backgroundColor: 'rgba(0, 0, 0, 0.4)', 
        zIndex: 200, 
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center', // Centers the content block vertically
        padding: '20px',
        boxSizing: 'border-box',
    };

    const contentStyle = {
        padding: '30px',
        backgroundColor: '#FFFFFF', // White background for content inside the modal
        border: `4px solid ${detail.color.border}`,
        borderRadius: '20px',
        textAlign: 'center',
        boxShadow: '0 10px 30px rgba(0,0,0,0.5)',
        width: '80%', // FIX: Smaller, fixed width relative to the screen
        maxHeight: '80vh', // Allow content to scroll if it gets too long
        overflowY: 'auto',
    };

    const textStyle = {
        fontSize: isEasyMode ? '36px' : '22px',
        lineHeight: '1.4',
        fontWeight: 'bold',
        color: '#333',
        margin: '20px 0',
    };
    
    const closeButtonStyle = {
        padding: '15px 30px',
        fontSize: isEasyMode ? '28px' : '18px',
        fontWeight: 'bold',
        borderRadius: '10px',
        border: 'none',
        cursor: 'pointer',
        marginTop: '20px',
        width: '100%',
        backgroundColor: '#ccc',
        color: '#333', 
    };

    return (
        <div style={modalStyle}>
            <div style={contentStyle}>
                <h3 style={{ fontSize: isEasyMode ? '40px' : '30px', color: detail.color.border, margin: '0 0 20px 0' }}>
                    {medication.name}
                </h3>
                
                {/* Simple Information for Elderly User (Easy Mode) */}
                <span style={{ fontSize: isEasyMode ? '90px' : '60px', display: 'block', margin: '15px 0' }}>
                    {detail.color.emoji}
                </span>

                <p style={textStyle}>
                    {medication.details}
                </p>

                {/* Button to close/go back */}
                <button 
                    onClick={onClose} 
                    style={closeButtonStyle}
                >
                    {t('general.back')}
                </button>
            </div>
        </div>
    );
};
// --- END MedicationDetailsModal ---


function MedicationHistoryPage({ isEasyMode, goToPage, onMenuClick }) {
    const { t } = useTranslation();
    const [selectedMedication, setSelectedMedication] = useState(null); // NEW STATE

    // --- Styles ---

    const listButtonStyle = {
        padding: '20px',
        margin: '15px 0',
        borderRadius: '10px',
        border: `3px solid ${detail.color.border}`,
        backgroundColor: detail.color.bg,
        textAlign: 'left',
        width: '100%',
        cursor: 'pointer',
        fontSize: isEasyMode ? '32px' : '20px',
        fontWeight: '900',
        color: detail.color.border,
        boxShadow: '0 4px 10px rgba(0,0,0,0.1)',
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
    };

    const preciseButtonStyle = {
        padding: '15px 30px', 
        fontSize: isEasyMode ? '24px' : '16px',
        fontWeight: 'bold',
        borderRadius: '10px',
        border: 'none',
        cursor: 'pointer',
        marginTop: '10px', 
        backgroundColor: '#DC3545', 
        color: 'white',
        boxShadow: '0 4px 10px rgba(0,0,0,0.3)',
        transition: 'background-color 0.2s',
    };

    const handleViewPrecise = () => {
        alert(`Opening PRECISE REPORT for ${detail.title} \nLink: ${detail.pdfLink}`);
        console.log(`Precise Report Link: ${detail.pdfLink}`);
    };

    return (
        <div 
            style={{ padding: '0 20px 20px 20px', maxWidth: PHONE_MAX_WIDTH, margin: '0 auto' }}
        >
            {/* Modal renders on top of everything */}
            <MedicationDetailsModal
                t={t}
                isEasyMode={isEasyMode}
                medication={selectedMedication}
                onClose={() => setSelectedMedication(null)}
            />

            <HeaderBar
                title={detail.title}
                onBackClick={() => goToPage('medical-history')} 
                onMenuClick={onMenuClick}
                isEasyMode={isEasyMode}
            />

            <h2 style={{ fontSize: isEasyMode ? '40px' : '30px', margin: '60px 0 10px 0', color: detail.color.border, textAlign: 'center' }}>
                {t('history_details.simple_summary')}
            </h2>
            
            <p style={{ fontSize: isEasyMode ? '22px' : '16px', textAlign: 'center', marginBottom: '30px', color: '#666' }}>
                {t('history_details.medication_tap_prompt')}
            </p>

            {/* --- Clickable Medication List --- */}
            <div style={{ maxWidth: '380px', margin: '0 auto' }}>
                {detail.medicationList.map(med => (
                    <button 
                        key={med.id}
                        onClick={() => setSelectedMedication(med)}
                        style={listButtonStyle}
                    >
                        {med.name} 
                        <span style={{ fontSize: isEasyMode ? '36px' : '24px', marginLeft: '10px' }}>&gt;</span>
                    </button>
                ))}
            </div>

            <p style={{ 
                fontSize: isEasyMode ? '20px' : '14px', 
                textAlign: 'center', 
                margin: '20px 0 30px 0',
                color: '#999'
            }}>
                {t('history_details.last_updated_label')}: {detail.lastUpdated}
            </p>
            
            {/* --- Call to Action for Caregivers/Others --- */}
            <h3 style={{ fontSize: isEasyMode ? '30px' : '20px', margin: '40px 0 10px 0', textAlign: 'center', color: '#666' }}>
                {t('history_details.precise_access_prompt')}
            </h3>

            <div style={{ textAlign: 'center' }}>
                <button onClick={handleViewPrecise} style={preciseButtonStyle}>
                    {t('history_details.view_precise_report')}
                </button>
                <p style={{ fontSize: isEasyMode ? '18px' : '12px', marginTop: '15px', color: '#999' }}>
                    {t('history_details.precise_report_note')}
                </p>
            </div>
        </div>
    );
}

export default MedicationHistoryPage;
